<template><div class="app-container"><el-alert title="访问日志不保存血糖值、用药内容等健康明文，只记录访问者、所有人、范围和结果。" type="info" :closable="false" style="margin-bottom:16px"/><div class="filter-container"><el-input v-model="query.ownerUserId" placeholder="数据所有人ID" style="width:160px"/><el-input v-model="query.viewerUserId" placeholder="访问人ID" style="width:160px"/><el-select v-model="query.accessResult" clearable placeholder="结果"><el-option label="允许" value="ALLOWED"/><el-option label="拒绝" value="DENIED"/></el-select><el-button type="primary" @click="load">查询</el-button></div><el-table :data="list" border><el-table-column prop="requestNo" label="访问编号" min-width="180"/><el-table-column prop="viewerUserId" label="访问人ID"/><el-table-column prop="ownerUserId" label="数据所有人ID"/><el-table-column prop="actionType" label="动作"/><el-table-column prop="scopeCode" label="范围"/><el-table-column prop="accessResult" label="结果"/><el-table-column prop="denyReason" label="拒绝原因" min-width="220"/><el-table-column prop="accessTime" label="访问时间" min-width="160"/></el-table></div></template><script>import{getJkHealthAccessLogList}from'@/api/jkBusiness';export default{data(){return{query:{page:1,limit:20},list:[]}},created(){this.load()},methods:{load(){getJkHealthAccessLogList(this.query).then(r=>this.list=(r&&r.list)||(r&&r.data&&r.data.list)||r.data||r||[])}}}</script>